CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,encrypted INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,updated_by TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS secret_store(id TEXT PRIMARY KEY,secret_name TEXT UNIQUE NOT NULL,ciphertext TEXT NOT NULL,key_version INTEGER NOT NULL,rotated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS channel_mappings(id INTEGER PRIMARY KEY AUTOINCREMENT,media_type TEXT NOT NULL,title_from TEXT NOT NULL,title_to TEXT NOT NULL,channel_name TEXT NOT NULL,channel_id TEXT,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS upload_rules(id INTEGER PRIMARY KEY CHECK(id=1),monthly_upload_limit_bytes INTEGER NOT NULL,chunk_size_bytes INTEGER NOT NULL,scheduling_enabled INTEGER NOT NULL,quotas_enabled INTEGER NOT NULL,sha_validation_enabled INTEGER NOT NULL,timezone TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS upload_windows(id INTEGER PRIMARY KEY AUTOINCREMENT,rule_id INTEGER NOT NULL REFERENCES upload_rules(id) ON DELETE CASCADE,weekday INTEGER NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cache_rules(id INTEGER PRIMARY KEY CHECK(id=1),r2_cache_size_bytes INTEGER NOT NULL,eviction_policy TEXT NOT NULL,cache_duration_seconds INTEGER NOT NULL,popularity_threshold INTEGER NOT NULL,preload_enabled INTEGER NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cloudflare_config(id INTEGER PRIMARY KEY CHECK(id=1),account_id TEXT,worker_url TEXT,worker_secret_ref TEXT,d1_database_id TEXT,kv_namespace TEXT,r2_bucket TEXT,pages_project TEXT,domain_name TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telegram_config(id INTEGER PRIMARY KEY CHECK(id=1),phone_number_ref TEXT,api_id_ref TEXT,api_hash_ref TEXT,session_name TEXT,session_ref TEXT,session_status TEXT NOT NULL DEFAULT 'disconnected',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jellyfin_config(id INTEGER PRIMARY KEY CHECK(id=1),server_url TEXT,api_key_ref TEXT,username TEXT,password_ref TEXT,library_paths TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tmdb_config(id INTEGER PRIMARY KEY CHECK(id=1),api_key_ref TEXT,language TEXT,region TEXT,poster_sync INTEGER NOT NULL DEFAULT 1,backdrop_sync INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS health_checks(id INTEGER PRIMARY KEY AUTOINCREMENT,component TEXT NOT NULL,status TEXT NOT NULL,last_check TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,latency_ms INTEGER,error TEXT);
CREATE INDEX IF NOT EXISTS idx_health_component ON health_checks(component,last_check);
